    add_box(bm, 22, -60.2, 0, 22.2, 0.2, 30)
    add_box(bm, -22, -60.2, 0, 22, -60, 30)
    add_box(bm, -22, 0, 0, -2.4, 0.2, 30)
    add_box(bm, 2.4, 0, 0, 22, 0.2, 30)
