    obj_from_bm('HallShell', bm, MAT['metal_panel'], C, loc=O)
    bm = bmesh.new()
    for sx in (-1, 1):
        for y in np.arange(-54, -2, 8.0):
            add_box(bm, sx * 21.9, y, 0.0, sx * 21.4, y + 1.6, 30)
    obj_from_bm('HallFins', bm, MAT['darksteel'], C, loc=O)
    bm = bmesh.new()
    for sx in (-1, 1):
        for y in np.arange(-54, -2, 8.0):
            add_box(bm, sx * 21.38, y + 0.7, 0.4, sx * 21.33, y + 0.9, 29.5)
        add_box(bm, sx * 18.0 - 0.1, -58, 0.0, sx * 18.0 + 0.1, -1, 0.03)
    obj_from_bm('HallStrips', bm, MAT['strip_cold'], C, loc=O)
    card('HallScreen', MAT['scr_logo'], 40.0, 22.5, O + Vector((0, -59.8, 15.5)), yaw=180, collection=C)
    area = bpy.data.lights.new('HallScreenLight', 'AREA')
    area.shape, area.size, area.size_y, area.energy = 'RECTANGLE', 40, 22.5, 60000.0
    area.color = (0.55, 0.7, 1.0)
