def dome_cam(name, loc, C):
    """Ceiling dome camera: a mount and a ball head (the head turns to track whoever is in the corridor)."""
    bm = bmesh.new()
    add_cyl(bm, 0.14, 0.14, 0.06, seg=16, matrix=Matrix.Translation(loc + Vector((0, 0, -0.03))))
    obj_from_bm(name + '_mount', bm, MAT['white_plastic'], C)
    head = empty(name, loc + Vector((0, 0, -0.12)), C)
    head.rotation_mode = 'XYZ'
    bm = bmesh.new()
    add_sphere(bm, 0.11, 16, 10, mi=0)
    add_cyl(bm, 0.045, 0.05, 0.08, seg=12, matrix=Matrix.Translation((0, 0.1, 0)) @ Matrix.Rotation(R(90), 4, 'X'), mi=1)
    add_sphere(bm, 0.012, 6, 4, Matrix.Translation((0.06, 0.08, 0.04)), mi=2)
    ob = obj_from_bm(name + '_head', bm, [MAT['black_glass'], MAT['lens_glass'], MAT['tally_red']], C, smooth=True)
    ob.parent = head
    return head


def aim(ob, target, base_fwd='+Y'):
    """Rotate an object so its local +Y points at target."""
    d = Vector(target) - ob.matrix_world.translation
    if d.length < 1e-6:
        return
    ob.rotation_euler = d.to_track_quat('Y', 'Z').to_euler()


# --- the news studio --------------------------------------------------------------------------------------------------
def build_news():
    C = 'News'
    O = NEWS
    bm = bmesh.new()
    add_box(bm, -12, -8, -0.2, 12, 8, 0)
    obj_from_bm('StudioFloor', bm, MAT['studio_floor'], C, loc=O)
    # curved video wall behind the desk
    verts, faces, uvs = [], [], []
    n = 40
    for i in range(n + 1):
        a = R(-60 + 120 * i / n)
        x, y = 9.0 * math.sin(a), 6.0 - 9.0 * (1 - math.cos(a)) * 0.4
        for z in (0.0, 5.2):
            verts.append(O + Vector((x, y, z)))
            uvs.append((i / n, z / 5.2))
    for i in range(n):
        faces.append((2 * i, 2 * i + 2, 2 * i + 3, 2 * i + 1))
    loops = np.array(faces).ravel()
    mesh_obj('NewsWall', verts, faces, MAT['news_wall'], C, smooth=True, uvs=np.array(uvs)[loops])
    card('NewsScreen', MAT['broadcast_mat'], 4.8, 2.7, O + Vector((1.6, 5.2, 2.75)), collection=C)
    card('NewsPortrait', MAT['portrait_glow'], 4.8 * 470 / 1600, 2.7 * 550 / 900, O + Vector((1.6 + 4.8 * (325 / 1600 - 0.5), 5.18, 2.75 + 2.7 * (0.5 - 425 / 900))),
         collection=C)
    bm = bmesh.new()
    add_box(bm, -0.9, 5.22, 1.3, 4.1, 5.35, 4.2)
    obj_from_bm('NewsScreenBack', bm, MAT['black_plastic'], C, loc=O)
    # desk
    verts, faces, uvs = [], [], []
    for i in range(25):
        a = R(-50 + 100 * i / 24)
        x, y = 3.2 * math.sin(a), 1.2 - 3.2 * (1 - math.cos(a))
        for z in (0.0, 0.8):
            verts.append(O + Vector((x, y, z)))
            uvs.append((i / 24, z / 0.8))
    faces = [(2 * i, 2 * i + 1, 2 * i + 3, 2 * i + 2) for i in range(24)]
    loops = np.array(faces).ravel()
    mesh_obj('DeskFront', verts, faces, MAT['desk_front'], C, smooth=True, uvs=np.array(uvs)[loops])
    V2, F2 = [], []
    for i in range(25):
        a = R(-50 + 100 * i / 24)
        x, y = 3.2 * math.sin(a), 1.2 - 3.2 * (1 - math.cos(a))
        V2 += [O + Vector((x * 1.02, y - 0.05, 0.8)), O + Vector((x * 1.02, y + 0.85, 0.8)),
               O + Vector((x * 1.02, y - 0.05, 0.85)), O + Vector((x * 1.02, y + 0.85, 0.85))]
    for i in range(24):
        b = 4 * i
        F2 += [(b + 2, b + 6, b + 7, b + 3), (b, b + 1, b + 5, b + 4), (b, b + 4, b + 6, b + 2)]
    mesh_obj('DeskTop', V2, F2, MAT['desk_top'], C, smooth=False)
    # studio truss + lights
    bm = bmesh.new()
    for y in (-4.0, 2.0):
        add_box(bm, -11, y - 0.15, 6.4, 11, y + 0.15, 6.7)
    for x in np.arange(-9, 10, 3.0):
        add_cyl(bm, 0.16, 0.2, 0.4, seg=10, matrix=Matrix.Translation((x, -4.0, 6.15)))
    obj_from_bm('Truss', bm, MAT['darksteel'], C, loc=O)
    area_light('NewsKey', O + Vector((-3.0, -4.5, 4.0)), (R(60), 0, R(-30)), 3.0, 2.0, 700.0, (1.0, 0.95, 0.9), C)
    area_light('NewsFill', O + Vector((3.5, -4.0, 3.0)), (R(65), 0, R(35)), 3.0, 2.0, 300.0, (0.75, 0.85, 1.0), C)
    area_light('NewsRim', O + Vector((0, 4.0, 4.5)), (R(-50), 0, 0), 4.0, 1.0, 400.0, (0.6, 0.8, 1.0), C)


