HERO_WIN = dict(x0=-1.4, x1=1.4, z0=10.9, z1=12.9)     # the hero window (4th floor)


def build_homes():
    C = 'Homes'
    O = HOMES
    W = HERO_WIN
    bm = bmesh.new()
    # facade at y = 0 (facing -y), x -45..45, z 0..45, with a hole for the hero window
    for (x0, x1, z0, z1) in ((-45, W['x0'], 0, 45), (W['x1'], 45, 0, 45), (W['x0'], W['x1'], 0, W['z0']), (W['x0'], W['x1'], W['z1'], 45)):
        add_box(bm, x0, 0, z0, x1, 14, z1)
    obj_from_bm('Block', bm, MAT['block_facade'], C, loc=O)
    # balconies + ledges every floor (the windows themselves are in the facade shader)
