    for sx in (-1, 1):
        add_box(bm, sx * 1.3 - 0.15, 2.2, z, sx * 1.3 + 0.15, 3.1, z + 0.65)
    obj_from_bm('Sofa', bm, MAT['sofa_fabric'], C, loc=O, smooth=False)
    bm = bmesh.new()
    add_box(bm, -0.9, 4.6, z, 0.9, 4.95, z + 0.5)
    obj_from_bm('TVUnit', bm, MAT['wood_dark'], C, loc=O)
    card('FlatTV', MAT['broadcast_mat'], 1.6, 0.9, O + Vector((0, 4.85, z + 1.15)), collection=C)
    card('FlatTVPortrait', MAT['portrait_glow'], 1.6 * 470 / 1600, 0.9 * 550 / 900, O + Vector((1.6 * (325 / 1600 - 0.5), 4.84, z + 1.15 + 0.9 * (0.5 - 425 / 900))),
         collection=C)
    SETS['tv_light'] = area_light('TVLight', O + Vector((0, 4.6, z + 1.15)), (R(-90), 0, 0), 1.6, 0.9, 30.0, (0.55, 0.7, 1.0), C)
    point_light('FlatLamp', O + Vector((-2.5, 3.6, z + 1.6)), 20.0, (1.0, 0.7, 0.45), C, radius=0.2)
    # family on the sofa: two stylised figures seen from behind
    for k, (x, coat) in enumerate(((-0.55, 'coat_brown'), (0.5, 'coat_teal'))):
        f = crowd_figure(f'Family{k}', coat, f'skin{k + 2}', 'hair_brown' if k else 'hair_black', 1.7, None, col=C)
        f.location = O + Vector((x, 2.55, z - 0.35))
