# --- the giant screen and the countdowns --------------------------------------------------------------------------------
SQ_STATE = {}


def set_screen_image(mat_name, tex):
    img = teximg(tex)
    for nn in ('Img', 'Img2'):
        nd_ = MAT[mat_name].node_tree.nodes[nn]
        if nd_.image != img:
            nd_.image = img


def square_screen(t, shot):
    """count -> stops at 00:00.00 -> static -> the name card; at night the leaked list."""
    S = SETS
    dig = S['sq_digits']
    port = S['sq_portrait']
    if shot == 'square2':
        set_screen_image('scr_square', 'leak')
        g = 0.9 * (1 - ramp(t, 50.9, 51.5)) + 0.25 * (0.5 + 0.5 * math.sin(t * 23.0)) * (t % 0.7 < 0.18)
        SV('g_square', g)
        SV('st_square', 0.6 * (1 - ramp(t, 50.85, 51.2)))
        dig.hide_render = True
        port.hide_render = True
        S['screen_light'].data.energy = 2.6e5
        S['screen_light'].data.color = (1.0, 0.75, 0.7)
        return
    if t < 2.25:
        set_screen_image('scr_square', 'sq_count')
        rem = max(0.0, 0.75 - t)
        dig.data.body = f'00:00.{int(round(rem * 100)):02d}'
        blink = 1.0 if t < 1.2 or (t * 3.0) % 1.0 < 0.6 else 0.25
        dig.hide_render = False
        SV('digits_e', 9.0 * blink)
        SV('g_square', 0.0)
        SV('st_square', 0.0)
        port.hide_render = True
        S['screen_light'].data.color = (0.55, 0.7, 1.0)
        S['screen_light'].data.energy = 1.6e5
    elif t < 2.45:
        dig.hide_render = True
        port.hide_render = True
        SV('g_square', 1.0)
        SV('st_square', 0.85)
        S['screen_light'].data.energy = 3.2e5
        S['screen_light'].data.color = (0.9, 0.95, 1.0)
    else:
        set_screen_image('scr_square', 'sq_name')
        dig.hide_render = True
        port.hide_render = False
        g = 0.4 * (1 - ramp(t, 2.45, 2.7))
        SV('g_square', g)
        SV('st_square', 0.0)
        S['screen_light'].data.color = (1.0, 0.62, 0.52)
        S['screen_light'].data.energy = 0.7e5


def SV(key, v):
    for s in SHOTVAL.get(key, []):
        s.default_value = v


def gantry_countdown(t):
    n = 3 - int(max(0.0, t - 23.4) / 0.6)
    n = max(n, 0)
    SETS['cd_digits'].data.body = f'00:{n:02d}' if n > 0 else '00:00'
    SV('digits_e', 9.0 if n > 0 or (t * 4) % 1.0 < 0.6 else 2.0)


# --- live dots on the arena map ----------------------------------------------------------------------------------------
DOTS = {}


def build_map_dots():
    """Twelve contestant dots in front of each map screen (tower and control room); "you" is amber with a pulse ring."""
    for key, (centre, size, yaw, C) in (('tower', (SETS['mapscreen'][1], 14.0, 0.0, 'Arena')),
                                        ('ctrl', (CTRL + Vector((0, 4.4 - 0.02, 1.55)), 1.75, 0.0, 'Ctrl'))):
        obs = []
        for k in range(12):
            bm = bmesh.new()
            add_cyl(bm, 1.0, 1.0, 0.02, seg=16, matrix=Matrix.Rotation(R(90), 4, 'X'))
            ob = obj_from_bm(f'Dot_{key}{k}', bm, MAT['dot_you' if k == 0 else 'dot_other'], C)
            obs.append(ob)
        bm = bmesh.new()
        add_cyl(bm, 1.0, 1.0, 0.02, seg=24, matrix=Matrix.Rotation(R(90), 4, 'X'))
        bmesh.ops.delete(bm, geom=[f for f in bm.faces if len(f.verts) > 4], context='FACES')
        ring = obj_from_bm(f'Ring_{key}', bm, MAT['dot_you'], C)
        DOTS[key] = dict(obs=obs, ring=ring, centre=centre, size=size)


def update_dots(key, t, you_xy):
    d = DOTS[key]
    sc = d['size'] * 0.46 / ARENA_R
    rr = d['size'] * 0.012
    for k, ob in enumerate(d['obs']):
        if k == 0:
            x, y = you_xy
        else:
            gx, gy = GATES[k]
            u = 0.25 + 0.02 * k + 0.01 * (t - 30.0)
            x, y = gx * (1 - u) + 40 * math.sin(k * 1.7 + t * 0.1), gy * (1 - u) + 40 * math.cos(k * 2.3 + t * 0.1)
        ob.location = d['centre'] + Vector((x * sc, -0.03, y * sc))
        s = rr * (1.4 if k == 0 else 1.0)
        ob.scale = (s, 1, s)
    ph = (t * 1.2) % 1.0
    d['ring'].location = d['obs'][0].location + Vector((0, -0.005, 0))
    d['ring'].scale = (rr * (1.5 + 4 * ph), 1, rr * (1.5 + 4 * ph))


# --- weather and the dome ------------------------------------------------------------------------------------------------
def lerp_light(a, b, u):
    out = {}
    for k in a:
        va, vb = a[k], b[k]
        if isinstance(va, tuple) and isinstance(va[0], tuple):
            out[k] = tuple(tuple(lerp(x, y, u) for x, y in zip(p, q)) if isinstance(p, tuple) else lerp(p, q, u) for p, q in zip(va, vb))
        elif isinstance(va, tuple):
            out[k] = tuple(lerp(x, y, u) if not isinstance(x, tuple) else tuple(lerp(i, j, u) for i, j in zip(x, y)) for x, y in zip(va, vb))
        else:
            out[k] = lerp(va, vb, u)
    return out


def update_world(t, shot):
    S = SETS
    SV('gtime', t)
    SV('beacon', 6.0 if (t * 1.1) % 1.0 < 0.25 else 0.3)
    # the square
    if shot in ('crowdcu', 'stage', 'turn', 'square2'):
        square_screen(t, shot)
        set_attr(S['crowd']['ob'], 'yaw', crowd_yaw(t, shot))
        S['phones'].hide_render = shot != 'square2'
        base, arm, head = S['crane']
        arm.rotation_euler = (R(-8 + 4 * math.sin(t * 0.7)), 0, R(-35 + 50 * ramp(t, 3.6, 5.4)))
        head.rotation_euler = (R(-12), 0, R(-25 + 30 * ramp(t, 3.6, 5.4)))
        for k, (dr, p) in enumerate(S['drones']):
            dr.location = p + Vector((1.5 * math.sin(t * 0.4 + k), 1.2 * math.cos(t * 0.33 + k), 0.4 * math.sin(t * 1.3 + k)))
            dr.rotation_euler = (R(4 * math.sin(t + k)), R(3 * math.cos(t * 1.2 + k)), R(30 * k + 8 * t))
        hd = S['herodrone']
        if shot == 'turn':
            u = smooth(ramp(t, 5.3, 6.8))
            hd.location = (YOU_SQ + Vector((3.0, 5.5, 9.5))).lerp(YOU_SQ + Vector((0.45, 2.1, 3.6)), u) + Vector((0, 0, 0.05 * math.sin(t * 6)))
            hd.rotation_euler = (R(-18), R(6 * math.sin(t * 2)), R(200))
            S['herospot'].data.energy = 600.0 * ramp(t, 5.6, 6.0)
            S['herospot'].location = hd.location + Vector((0, 0, -0.16))
            S['herospot'].rotation_euler = (YOU_SQ + Vector((0, 0, 1.2)) - hd.location).to_track_quat('-Z', 'Y').to_euler()
        else:
            hd.location = (0, 0, -100)
            S['herospot'].data.energy = 0.0
    # the arena
    if shot in ('gate', 'reveal', 'countdown', 'aerial'):
        u = doors_open(t) if shot != 'gate' or True else 0.0
        if shot != 'gate':
            u = 1.0
        for sx, lf in zip((-1, 1), S['gates'][0][1]):
            lf.location = (sx * (3.5 + 7.3 * u), 0, 0)
        others = smooth(ramp(t, 26.0, 27.5)) if shot == 'aerial' else (1.0 if shot == 'countdown' else 0.0)
        for k, (root, leaves) in enumerate(S['gates'][1:]):
            v = others if shot == 'aerial' else 0.0
            for sx, lf in zip((-1, 1), leaves):
                lf.location = (sx * (3.5 + 7.3 * v), 0, 0)
        SV('haze', 0.0)
        SV('tunnel_e', 3.0)
        if shot == 'countdown':
            gantry_countdown(t)
        else:
            SETS['cd_digits'].data.body = '00:03'
    for k, h in enumerate(S['towercams']):
        h.rotation_euler = (R(-25), 0, R(40 * k + 20 * math.sin(t * 0.3 + k)))
    if shot == 'map':
        update_dots('tower', t, (-24.0, -538.0))
    if shot in ('control', 'list', 'faceglow', 'switch', 'camturn', 'stare'):
        update_dots('ctrl', t, (150.0, -466.0))
    door, dp = S['hidden_door']
    if shot == 'door':
        u = door_open(t)
        door.location = dp + Vector((2.3 * u, 0, 0))
        SV('seam', 2.0 + 6.0 * ramp(t, 39.3, 39.7) + 4.0 * u)
        S['door_light'].data.energy = 120.0 * u
    else:
        door.location = dp
        S['door_light'].data.energy = 0.0
    # sky: weather on cue, the dome glitch
    if shot == 'weather':
        u = smooth(ramp(t, 33.0, 34.7))
        set_light(lerp_light(L_FOREST, L_STORM, u), SHOTCFG[shot])
        SV('dome_glitch', 0.0)
        SV('wind', 0.4 + 1.6 * u)
    elif shot == 'dome':
        g = ramp(t, 37.1, 37.35) * (1 - 0.6 * ramp(t, 38.3, 38.9))
        flick = 1.0 if (t * 9.0) % 1.0 < 0.6 else 0.35
        SV('dome_glitch', g * flick)
    else:
        SV('dome_glitch', 0.0)
    # control room monitors: glitch when the feeds are switched to every channel; red LIVE tint afterwards
    if shot in ('switch', 'camturn', 'stare'):
        g = ramp(t, 49.6, 49.75) * (1 - ramp(t, 50.4, 50.8)) + (0.15 if (t * 5) % 1.0 < 0.15 else 0.0)
        SV('g_mon', g)
        SV('live', ramp(t, 50.0, 50.5) if shot == 'switch' else 1.0)
    else:
        SV('g_mon', 0.02)
        SV('live', 0.0)


CHOR = {
    'crowdcu': chor_square, 'stage': chor_square, 'turn': chor_square, 'square2': None,
    'hall': chor_hall, 'news': chor_news, 'homes': None, 'logo': chor_logo,
    'gate': chor_gate, 'reveal': chor_gate, 'countdown': chor_countdown, 'aerial': chor_aerial,
    'camlens': chor_forest, 'map': chor_map, 'weather': chor_weather, 'others': chor_others, 'dome': chor_dome,
    'door': chor_door, 'control': chor_ctrl, 'list': chor_ctrl, 'faceglow': chor_ctrl,
    'switch': chor_ctrl, 'camturn': chor_ctrl, 'stare': chor_ctrl,
}


def animate(t, shot):
    for k in list(CAST) + [YOU]:
        park(k)
    fn = CHOR.get(shot)
    if fn is not None:
        fn(t, shot)
    update_world(t, shot)

# ============================================================================
# Materials
# ============================================================================
def V_(nt, m, key, v):
    """A Value node registered under `key` (animated per shot / per frame through SHOTVAL)."""
    s = value(nt, key, v)
    register_value(m, key, key)
    return s


def screen_mat(name, tex, gkey, strength, skey=None, overlay=None, live=False, ekey=None):
    """An LED / LCD screen: emissive image, faint scanlines, horizontal-band glitch (gkey), TV static (skey), an
    optional RGBA overlay (HUD) and an optional red "LIVE" wash (live)."""
    m, nt, out = new_mat(name)
    uv = nd(nt, 'ShaderNodeTexCoord').outputs['UV']
    s = sep(nt, uv)
    g = V_(nt, m, gkey, 0.0)
    tt = V_(nt, m, 'gtime', 0.0)
    band = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 26.0))
    bt = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', tt, 12.0))
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=comb(nt, band, bt, 0.0))
    sel = mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['X'], 0.55)
    off = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', wn.outputs['Value'], 0.5), g), mth(nt, 'MULTIPLY', sel, 0.5))
    u2 = mth(nt, 'ADD', s.outputs['X'], off)
    img = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND', Vector=comb(nt, u2, s.outputs['Y'], 0.0))
    img.name = 'Img'
    col = img.outputs['Color']
    # chromatic split while glitching: shift red one way
    img2 = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND',
              Vector=comb(nt, mth(nt, 'ADD', u2, mth(nt, 'MULTIPLY', g, 0.012)), s.outputs['Y'], 0.0))
    img2.name = 'Img2'
    sp = nd(nt, 'ShaderNodeSeparateColor', Color=col)
    sp2 = nd(nt, 'ShaderNodeSeparateColor', Color=img2.outputs['Color'])
    col = nd(nt, 'ShaderNodeCombineColor', Red=sp2.outputs['Red'], Green=sp.outputs['Green'], Blue=sp.outputs['Blue']).outputs[0]
    if overlay:
        ov = nd(nt, 'ShaderNodeTexImage', p_image=teximg(overlay), p_interpolation='Linear', p_extension='EXTEND', Vector=uv)
        col = mixc(nt, ov.outputs['Alpha'], col, ov.outputs['Color'])
    if skey:
        st = V_(nt, m, skey, 0.0)
        wn2 = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D',
                 Vector=comb(nt, mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['X'], 320.0)),
                             mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 180.0)), mth(nt, 'MULTIPLY', tt, 30.0)))
        col = mixc(nt, st, col, wn2.outputs['Color'])
    if live:
        lv = V_(nt, m, 'live', 0.0)
        red = mixc(nt, 0.5, col, (1.0, 0.1, 0.08, 1))
        col = mixc(nt, mth(nt, 'MULTIPLY', lv, 0.35), col, red)
    lines = mth(nt, 'MULTIPLY_ADD', mth(nt, 'SINE', mth(nt, 'MULTIPLY', s.outputs['Y'], 1400.0)), 0.07, 0.93)
    strength = V_(nt, m, ekey, strength) if ekey else strength
    e = nd(nt, 'ShaderNodeEmission', Color=col, Strength=mth(nt, 'MULTIPLY', lines, strength))
    gl_ = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.08, Color=(0.04, 0.04, 0.045, 1))
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(e.outputs[0], ad.inputs[0])
    nt.links.new(gl_.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def glow_img(name, tex, strength, alpha=False):
    m, nt, out = new_mat(name)
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND')
    e = nd(nt, 'ShaderNodeEmission', Color=t.outputs['Color'], Strength=strength)
    if alpha:
        tr = nd(nt, 'ShaderNodeBsdfTransparent')
        mx = nd(nt, 'ShaderNodeMixShader', Fac=t.outputs['Alpha'])
        nt.links.new(tr.outputs[0], mx.inputs[1])
        nt.links.new(e.outputs[0], mx.inputs[2])
        nt.links.new(mx.outputs[0], out.inputs['Surface'])
    else:
        nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def future_facade(name, glass, frame, mull=1.6, floor=4.2, band=(0.55, 0.8, 1.0), lit=0.22, stone=False):
    """Curtain-wall towers: glass between mullions and floor slabs, a glowing band every few floors, some lit windows."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    h = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    z = s_.outputs['Z']
    u = mth(nt, 'FRACT', mth(nt, 'DIVIDE', h, mull))
    v = mth(nt, 'FRACT', mth(nt, 'DIVIDE', z, floor))
    fw = 0.22 if stone else 0.06
    pane = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, fw), mth(nt, 'LESS_THAN', u, 1 - fw)),
               mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.16 if stone else 0.1), mth(nt, 'LESS_THAN', v, 0.92)))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', h, mull)), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor)), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell)
    gcol = mixc(nt, mth(nt, 'MULTIPLY', wn.outputs['Value'], 0.6), rgba(glass), rgba([min(1, c * 1.6) for c in glass]))
    col = mixc(nt, pane, rgba(frame), gcol)
    rough = mth(nt, 'ADD', mth(nt, 'MULTIPLY', pane, -0.6), 0.7)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Metallic': mth(nt, 'MULTIPLY', pane, 0.0 if stone else 0.6),
                               'Specular IOR Level': 0.6})
    fl = mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor))
    bandm = mth(nt, 'MULTIPLY', mth(nt, 'LESS_THAN', mth(nt, 'MODULO', fl, 6.0), 0.5), mth(nt, 'LESS_THAN', v, 0.08))
    on = mth(nt, 'MULTIPLY', pane, mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['Y'], 1 - lit))
    em = mixc(nt, bandm, (1.0, 0.85, 0.65, 1), rgba(band))
    nt.links.new(em, p.inputs['Emission Color'])
    lv = V_(nt, m, 'citylit', 1.0)
    nt.links.new(mth(nt, 'MULTIPLY', mth(nt, 'ADD', mth(nt, 'MULTIPLY', bandm, 6.0), mth(nt, 'MULTIPLY', on, 1.4)), lv), p.inputs['Emission Strength'])
    MAT[name] = m


def block_facade():
    """Apartment block at night: every window shows the same broadcast (a blue-white TV flicker in sync)."""
    m, nt, out = new_mat('block_facade')
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    h = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    z = s_.outputs['Z']
    u = mth(nt, 'FRACT', mth(nt, 'DIVIDE', h, 2.8))
    v = mth(nt, 'FRACT', mth(nt, 'DIVIDE', z, 3.0))
    win = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, 0.2), mth(nt, 'LESS_THAN', u, 0.8)),
              mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.3), mth(nt, 'LESS_THAN', v, 0.85)))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', h, 2.8)), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, 3.0)), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell)
    n = noise(nt, 0.3, 3.0, 0.5, vec=oc)
    wall = mixc(nt, mth(nt, 'MULTIPLY', n, 0.5), (0.30, 0.30, 0.32, 1), (0.18, 0.18, 0.2, 1))
    glass = (0.02, 0.025, 0.03, 1)
    col = mixc(nt, win, wall, glass)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': mth(nt, 'ADD', mth(nt, 'MULTIPLY', win, -0.75), 0.85)})
    flick = V_(nt, m, 'tvflick', 1.0)
    on = mth(nt, 'MULTIPLY', win, mth(nt, 'GREATER_THAN', wn.outputs['Value'], 0.3))
    warm = mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['Y'], 0.82)
    ecol = mixc(nt, warm, (0.25, 0.45, 1.0, 1), (1.0, 0.62, 0.32, 1))
    nt.links.new(ecol, p.inputs['Emission Color'])
    lvl = mth(nt, 'MULTIPLY', on, mth(nt, 'ADD', mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', 1.0, warm), flick), mth(nt, 'MULTIPLY', warm, 0.5)))
    nt.links.new(mth(nt, 'MULTIPLY', lvl, mth(nt, 'MULTIPLY_ADD', sep(nt, wn.outputs['Color']).outputs['Z'], 0.22, 0.08)), p.inputs['Emission Strength'])
    MAT['block_facade'] = m


def arena_ground():
    """Meadow grass, forest floor, rock on steep slopes, snow on the peaks (object coords; height and slope)."""
    m, nt, out = new_mat('arena_ground')
    oc = obj_coord(nt)
    z = sep(nt, oc).outputs['Z']
    nz = sep(nt, nd(nt, 'ShaderNodeNewGeometry').outputs['Normal']).outputs['Z']
    n1 = noise(nt, 0.02, 4.0, 0.6, vec=oc)
    n2 = noise(nt, 0.35, 3.0, 0.6, vec=oc)
    n3 = noise(nt, 4.0, 2.0, 0.5, vec=oc)
    grass = mixc(nt, mth(nt, 'MULTIPLY', n2, 1.0), (0.10, 0.20, 0.035, 1), (0.22, 0.30, 0.07, 1))
    grass = mixc(nt, mth(nt, 'MULTIPLY', n3, 0.5), grass, (0.16, 0.22, 0.06, 1))
    dirt = mixc(nt, n2, (0.14, 0.10, 0.06, 1), (0.08, 0.06, 0.04, 1))
    rock = mixc(nt, n3, (0.32, 0.31, 0.30, 1), (0.20, 0.19, 0.18, 1))
    snow = (0.85, 0.87, 0.9, 1)
    col = mixc(nt, mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', n1, 0.62), 0.6), grass, dirt)
    steep = mth(nt, 'SUBTRACT', 1.0, mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', nz, 0.72), 6.0), clamp=True)
    col = mixc(nt, steep, col, rock)
    high = mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', z, mth(nt, 'MULTIPLY_ADD', n1, 80.0, 300.0)), 0.04, clamp=True)
    col = mixc(nt, mth(nt, 'MAXIMUM', mth(nt, 'MULTIPLY', high, 0.7), 0.0), col, rock)
    snowy = mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', z, mth(nt, 'MULTIPLY_ADD', n1, 60.0, 380.0)), 0.05, clamp=True)
    col = mixc(nt, mth(nt, 'MULTIPLY', snowy, mth(nt, 'GREATER_THAN', nz, 0.5)), col, snow)
    bump = nd(nt, 'ShaderNodeBump', Strength=0.25, Height=n3)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': 0.92})
    nt.links.new(bump.outputs[0], p.inputs['Normal'])
    MAT['arena_ground'] = m


def dome_panel():
    """The dome's panels: invisible (the "sky" is a projection) until the glitch: then some panels die (black), some flare
    cyan-white, and the rest flicker faintly."""
    m, nt, out = new_mat('dome_panel')
    at = nt.nodes.new('ShaderNodeAttribute')
    at.attribute_name = 'rnd'
    r = at.outputs['Fac']
    g = V_(nt, m, 'dome_glitch', 0.0)
    tt = V_(nt, m, 'gtime', 0.0)
    ph = mth(nt, 'FRACT', mth(nt, 'ADD', mth(nt, 'MULTIPLY', r, 17.0), mth(nt, 'MULTIPLY', tt, 2.5)))
    zone = mth(nt, 'LESS_THAN', r, 0.6)
    flare = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', ph, 0.84), g), zone)
    dead = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'LESS_THAN', ph, 0.2), g), zone)
    ecol = mixc(nt, mth(nt, 'GREATER_THAN', r, 0.5), (0.3, 0.7, 1.0, 1), (0.85, 0.95, 1.0, 1))
    e = nd(nt, 'ShaderNodeEmission', Color=ecol, Strength=mth(nt, 'MULTIPLY', flare, 3.0))
    tr = nd(nt, 'ShaderNodeBsdfTransparent', Color=(1, 1, 1, 1))
    bl = nd(nt, 'ShaderNodeBsdfDiffuse', Color=(0.01, 0.012, 0.016, 1))
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'ADD', 0.0, mth(nt, 'MULTIPLY', dead, 0.92)))
    nt.links.new(tr.outputs[0], mx.inputs[1])
    nt.links.new(bl.outputs[0], mx.inputs[2])
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(mx.outputs[0], ad.inputs[0])
    nt.links.new(e.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])
    MAT['dome_panel'] = m
    m, nt, out = new_mat('dome_strut')
    g = V_(nt, m, 'dome_glitch', 0.0)
    principled(nt, out, **{'Base Color': (0.5, 0.52, 0.55, 1), 'Roughness': 0.4, 'Metallic': 0.8, 'Emission Color': (0.4, 0.8, 1.0, 1),
                           'Emission Strength': mth(nt, 'MULTIPLY', g, 4.0)})
    MAT['dome_strut'] = m


def river_material():
    m, nt, out = new_mat('river')
    oc = obj_coord(nt)
    tt = V_(nt, m, 'gtime', 0.0)
    v = nd(nt, 'ShaderNodeVectorMath', p_operation='ADD', Vector=oc)
    nt.links.new(comb(nt, mth(nt, 'MULTIPLY', tt, 0.6), 0.0, mth(nt, 'MULTIPLY', tt, 0.2)), v.inputs[1])
    n = noise(nt, 0.4, 5.0, 0.6, vec=v.outputs[0])
    bump = nd(nt, 'ShaderNodeBump', Strength=0.3, Height=n)
    p = principled(nt, out, **{'Base Color': (0.03, 0.07, 0.07, 1), 'Roughness': 0.04, 'Specular IOR Level': 0.9, 'Coat Weight': 0.3})
    nt.links.new(bump.outputs[0], p.inputs['Normal'])
    MAT['river'] = m


def panel_metal(name, base, size=(1.2, 1.2), rough=0.35):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    hx = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    a = mth(nt, 'FRACT', mth(nt, 'DIVIDE', hx, size[0]))
    b = mth(nt, 'FRACT', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1]))
    seam = mth(nt, 'MAXIMUM', mth(nt, 'LESS_THAN', a, 0.012), mth(nt, 'LESS_THAN', b, 0.012))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', hx, size[0])), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1])), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell).outputs['Value']
    col = mixc(nt, mth(nt, 'MULTIPLY', wn, 0.35), rgba(base), rgba([c * 1.4 for c in base]))
    col = mixc(nt, seam, col, (0.005, 0.005, 0.006, 1))
    principled(nt, out, **{'Base Color': col, 'Metallic': 0.75, 'Roughness': mth(nt, 'ADD', rough, mth(nt, 'MULTIPLY', wn, 0.15))})
    MAT[name] = m


def glass_window_material():
    m, nt, out = new_mat('window_glass')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.25)
    tp = nd(nt, 'ShaderNodeBsdfTransparent', Color=(0.96, 0.98, 0.98, 1))
    gl = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.02)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY_ADD', lw.outputs['Fresnel'], 0.6, 0.04))
    nt.links.new(tp.outputs[0], mx.inputs[1])
    nt.links.new(gl.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['window_glass'] = m


def build_materials():
    eye_material()
    flat_mat('mouth', (0.10, 0.02, 0.025), rough=0.4)
    for k, c in enumerate(((0.80, 0.56, 0.42), (0.50, 0.30, 0.18), (0.86, 0.64, 0.50), (0.36, 0.22, 0.14), (0.70, 0.48, 0.34))):
        skin_mat(f'skin{k}', c)
    for name, c in (('hair_brown', (0.12, 0.065, 0.035)), ('hair_black', (0.025, 0.02, 0.018))):
        simple_mat(name, c, rough=0.45, noise_amt=0.3, noise_scale=60.0, coat=0.2)
    cloth_mat('jacket_rust', (0.24, 0.04, 0.018), weave=90.0)
    cloth_mat('shirt_white', (0.80, 0.80, 0.80))
    cloth_mat('trousers_dark', (0.05, 0.055, 0.065), weave=110.0)
    cloth_mat('suit_charcoal', (0.07, 0.075, 0.085), weave=140.0)
    flat_mat('tie', (0.35, 0.03, 0.04), rough=0.4)
    cloth_mat('uniform', (0.025, 0.028, 0.032), weave=120.0)
    flat_mat('vest', (0.05, 0.055, 0.06), rough=0.6)
    cloth_mat('blazer_blue', (0.05, 0.10, 0.24), weave=120.0)
    cloth_mat('jacket_teal', (0.04, 0.20, 0.20), weave=90.0)
    cloth_mat('jacket_grey', (0.22, 0.23, 0.24), weave=90.0)
    for name, c in (('coat_navy', (0.04, 0.06, 0.13)), ('coat_grey', (0.25, 0.26, 0.28)), ('coat_char', (0.08, 0.08, 0.09)),
                    ('coat_olive', (0.13, 0.15, 0.08)), ('coat_brown', (0.18, 0.11, 0.07)), ('coat_slate', (0.13, 0.17, 0.21)),
                    ('coat_black', (0.02, 0.02, 0.025)), ('coat_teal', (0.04, 0.13, 0.14))):
        cloth_mat(name, c, weave=70.0)
    for name, c in (('shoe_white', (0.85, 0.85, 0.84)), ('shoe_black', (0.02, 0.02, 0.02))):
        flat_mat(name, c, rough=0.45, coat=0.2)
    emission_mat('tracker_glow', (0.3, 0.9, 1.0), 12.0)
